import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"竞争与临界区","description":"","frontmatter":{"title":"竞争与临界区","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/race-critical.md","filePath":"cs/race-critical.md","lastUpdated":1789023840000}'),h={name:"cs/race-critical.md"};function E(_,a,m,A,u,f){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="竞争与临界区" tabindex="-1">竞争与临界区 <a class="header-anchor" href="#竞争与临界区" aria-label="Permalink to &quot;竞争与临界区&quot;">​</a></h1><div class="epigraph"><p>并发程序的正确性不能依赖「刚好不会交错」；必须标出一次只许一个执行流进入的代码区间。</p><footer>—— 据 Dijkstra, Cooperating Sequential Processes, 1965；Silberschatz et al. 整理</footer></div><p><a href="/cs/numa-sched">上一课</a>让进程经内核缓冲传字节；<a href="/cs/thread-shared-addr">线程</a>还能直接改同一堆。调度与中断随时切开指令序列。缺口是：对共享变量的「读改写」一旦交错，结果不再是任何一方的顺序意图。本课命名竞争与临界区，不给出锁的实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>计数器 <code>n++</code> 在机器上常是载入、加一、写回。两条线程各加一次，交错后可能只加一次。管道缓冲的头尾指针同样。缺口不是新的 IPC 种类，而是承认<strong>并发对象</strong>有不变量，必须在临界区里维护：区内禁止另一竞争者进入。</p><p>本课的临界区是逻辑区间，不是 x86 的临界指令前缀。互斥如何用关中断或原子指令做成，下一课。</p><p><span class="marginnote">竞争是「结果依赖于交错」。数据竞争常特指无同步的冲突访存；本课先用更宽的「竞争」：共享不变量被交错打破。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出共享状态与不变量（例如「缓冲中字节数 = 头减尾」）。把所有可能打破它的指令收进临界区。要求：互斥、有限等待、空闲让进（Dijkstra 的条件）。正确性用交错论证：区内相当于原子。本课不写形式模型；<a href="/cs/loop-invariant">循环不变量</a>的精神在并发里变成「锁外看不见中间态」。</p>',9)),(e(),n(p,null,{default:r(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHARE%5B%22%E5%85%B1%E4%BA%AB%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%20--%3E%20CS%5B%22%E4%B8%B4%E7%95%8C%E5%8C%BA%22%5D%0A%20%20CS%20--%3E%20MUTEX%5B%22%E4%B8%80%E6%AC%A1%E4%B8%80%E4%B8%AA%E6%89%A7%E8%A1%8C%E6%B5%81%22%5D%0A%20%20MUTEX%20--%3E%20LOCK%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%A6%82%E4%BD%95%E5%AE%9E%E7%8E%B0%E4%BA%92%E6%96%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>没有临界区，管道与共享堆都不能谈正确，只能谈「多跑几次碰巧对」。有了临界区，调度可以任意抢占：只要不在无锁情况下改共享元数据。信号处理器若碰同一变量，也是竞争者——上一课的可重入在这里落地。</p><p>生产者—消费者的「缓冲满/空」还要等待，不只互斥；那是信号量与管程的缺口。本课只处理「不能同时进」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入内存模型的 happens-before，不把无锁算法当主干，也不把越界写当成同步问题：那是更后的安全课。也不把数据库事务隔离混进来。</p><p>编译器可以把无锁共享读写优化掉；临界区必须配内存屏障或语言级原子，细节在锁课落地。</p><p>本课不把「看起来像原子的一行 C」当成临界区。</p><p>后课默认：共享不变量只在临界区里改。临界区如何做成互斥——关中断、自旋、锁——下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交错会打破共享不变量；临界区一次只许一个竞争者。</li><li>互斥条件先于锁的实现。</li><li>等待「条件成立」超出本课，走向信号量。</li><li>出处：Dijkstra, <em>Cooperating Sequential Processes</em>, 1965；Silberschatz et al., <em>OSC</em>。</li></ul>',10))])}const S=o(h,[["render",E]]);export{C as __pageData,S as default};
